const deleteClaimedSoftDeletedDocument = `-- name: DeleteClaimedSoftDeletedDocument :execrows
DELETE FROM documents d
WHERE d.id = $1
  AND d.org_id = $2
  AND d.deleted_at IS NOT NULL
  AND d.deleted_at < $3
  AND d.status = 'draft'
  AND d.updated_at = $4
  AND NOT EXISTS (SELECT 1 FROM data_subject_requests r
      WHERE r.org_id = d.org_id AND (r.document_id = d.id OR r.document_id IS NULL)
        AND r.status IN ('open','in_progress'))
`

type DeleteClaimedSoftDeletedDocumentParams struct {
	ID        uuid.UUID          `json:"id"`
	OrgID     uuid.UUID          `json:"org_id"`
	DeletedAt pgtype.Timestamptz `json:"deleted_at"`
	UpdatedAt pgtype.Timestamptz `json:"updated_at"`
}

// Hard-delete only the exact draft lease the worker just cleaned. If any
// concurrent state change touched updated_at, the CAS fails and no legal row is
// removed. events.document_id uses ON DELETE SET NULL, preserving the org chain.
func (q *Queries) DeleteClaimedSoftDeletedDocument(ctx context.Context, arg DeleteClaimedSoftDeletedDocumentParams) (int64, error) {
	result, err := q.db.Exec(ctx, deleteClaimedSoftDeletedDocument,
		arg.ID,
		arg.OrgID,
		arg.DeletedAt,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const deleteDraftDocument = `-- name: DeleteDraftDocument :exec
UPDATE documents
SET deleted_at = now()
WHERE id = $1 AND org_id = $2 AND status = 'draft' AND deleted_at IS NULL
`

type DeleteDraftDocumentParams struct {
	ID    uuid.UUID `json:"id"`
	OrgID uuid.UUID `json:"org_id"`
}

// Soft-delete: flip deleted_at so the row stays available for GDPR
// Art. 15 / Art. 30 evidence retrieval during the 90-day grace
// window. A separate worker prunes anything past that boundary.
func (q *Queries) DeleteDraftDocument(ctx context.Context, arg DeleteDraftDocumentParams) error {
	_, err := q.db.Exec(ctx, deleteDraftDocument, arg.ID, arg.OrgID)
	return err
}

